function pageAsset(name,other=name,size=null,extra=''){
 const d=PAGE_DIMENSIONS[name];if(!d)return '';
 const bitmap=!name.endsWith('.svg'),w=bitmap&&size?size:parseFloat(d.width),h=bitmap&&size?size:parseFloat(d.height);
 return themedAsset('assets/cliently/pages/'+name,'assets/cliently/pages/'+other,w,h,extra);
}
